import { isMenu, NAVIGATION } from "@/config/navigation";
import { slugOf, type PageData, type SeoTag } from "@/lib/pages";

export const SITE_ORIGIN = "https://theschoemanclinic.com";
export const OG_SIZE = { width: 1200, height: 630 };

/** The address of a page's share image, generated by app/og/[...slug]/route.tsx. */
export function ogImagePath(page: PageData): string {
  const slug = slugOf(page);
  return `/og/${slug.length ? slug.join("/") : "home"}.png`;
}

/** The route segments of a share image's address, back to the page: ["clinic", "wimbledon.png"]. */
export function ogImageSlug(page: PageData): string[] {
  return ogImagePath(page)
    .replace(/^\/og\//, "")
    .split("/");
}

/** The small heading over the title on a share image: the part of the site the page belongs to. */
export function ogEyebrow(page: PageData): string {
  if (page.themeStyles.includes("article")) return "Insights & Research";
  if (page.themeStyles.includes("bio")) return "Our Specialists";
  for (const item of NAVIGATION) {
    if (!isMenu(item)) continue;
    for (const column of item.columns) {
      if (column.links.some((link) => link.href === page.path)) {
        return item.key === "approach" ? column.heading.replace(/^The /, "") : item.label;
      }
    }
  }
  return "A Private London Clinic";
}

/** The title on a share image: the page's Open Graph title without the clinic's name. */
export function ogTitle(page: PageData): string {
  const tag = page.seo.find((t) => t.tag === "meta" && t.attrs.property === "og:title");
  const title = tag?.attrs.content ?? page.seo.find((t) => t.tag === "title")?.text ?? "";
  return title.split(/ [|–] (?=(The )?Schoeman)/)[0].trim();
}

const IMAGE_TAGS = new Set([
  "og:image",
  "og:image:width",
  "og:image:height",
  "og:image:type",
  "og:image:alt",
  "twitter:image",
]);
const key = (t: SeoTag) => t.attrs.property ?? t.attrs.name ?? "";

/**
 * A page's SEO tags with its generated share image in place of the one WordPress set (one picture,
 * reused on most pages, in WebP, which some apps do not show). Pages kept out of search keep none.
 */
export function seoWithShareImage(page: PageData): SeoTag[] {
  const noindex = page.seo.some((t) => key(t) === "robots" && /noindex/.test(t.attrs.content ?? ""));
  if (noindex || !page.seo.some((t) => key(t) === "og:title")) return page.seo;
  const url = `${SITE_ORIGIN}${ogImagePath(page)}`;
  const image: SeoTag[] = [
    { tag: "meta", attrs: { property: "og:image", content: url } },
    { tag: "meta", attrs: { property: "og:image:width", content: String(OG_SIZE.width) } },
    { tag: "meta", attrs: { property: "og:image:height", content: String(OG_SIZE.height) } },
    { tag: "meta", attrs: { property: "og:image:type", content: "image/png" } },
    { tag: "meta", attrs: { property: "og:image:alt", content: ogTitle(page) } },
  ];
  const tags = page.seo.filter((t) => !(t.tag === "meta" && IMAGE_TAGS.has(key(t))));
  // Where WordPress put the image: after the last og:/article: tag, before the Twitter ones.
  const at = tags.findLastIndex((t) => t.tag === "meta" && /^(og|article):/.test(key(t))) + 1;
  tags.splice(at, 0, ...image);
  const card = tags.findIndex((t) => key(t) === "twitter:card");
  if (card >= 0) tags.splice(card + 1, 0, { tag: "meta", attrs: { name: "twitter:image", content: url } });
  return tags;
}
